1	static void binder_transaction(struct binder_proc *proc,
2				       struct binder_thread *thread,
3				       struct binder_transaction_data *tr, int reply,
4				       binder_size_t extra_buffers_size)
5	{
6		int ret;
7		struct binder_transaction *t;
8		struct binder_work *w;
9		struct binder_work *tcomplete;
10		binder_size_t buffer_offset = 0;
11		binder_size_t off_start_offset, off_end_offset;
12		binder_size_t off_min;
13		binder_size_t sg_buf_offset, sg_buf_end_offset;
14		binder_size_t user_offset = 0;
15		struct binder_proc *target_proc = NULL;
16		struct binder_thread *target_thread = NULL;
17		struct binder_node *target_node = NULL;
18		struct binder_transaction *in_reply_to = NULL;
19		struct binder_transaction_log_entry *e;
20		uint32_t return_error = 0;
21		uint32_t return_error_param = 0;
22		uint32_t return_error_line = 0;
23		binder_size_t last_fixup_obj_off = 0;
24		binder_size_t last_fixup_min_off = 0;
25		struct binder_context *context = proc->context;
26		int t_debug_id = atomic_inc_return(&binder_last_id);
27		ktime_t t_start_time = ktime_get();
28		char *secctx = NULL;
29		u32 secctx_sz = 0;
30		struct list_head sgc_head;
31		struct list_head pf_head;
32		const void __user *user_buffer = (const void __user *)
33					(uintptr_t)tr->data.ptr.buffer;
34		INIT_LIST_HEAD(&sgc_head);
35		INIT_LIST_HEAD(&pf_head);
36	
37		e = binder_transaction_log_add(&binder_transaction_log);
38		e->debug_id = t_debug_id;
39		e->call_type = reply ? 2 : !!(tr->flags & TF_ONE_WAY);
40		e->from_proc = proc->pid;
41		e->from_thread = thread->pid;
42		e->target_handle = tr->target.handle;
43		e->data_size = tr->data_size;
44		e->offsets_size = tr->offsets_size;
45		strscpy(e->context_name, proc->context->name, BINDERFS_MAX_NAME);
46	
47		binder_inner_proc_lock(proc);
48		binder_set_extended_error(&thread->ee, t_debug_id, BR_OK, 0);
49		binder_inner_proc_unlock(proc);
50	
51		if (reply) {
52			binder_inner_proc_lock(proc);
53			in_reply_to = thread->transaction_stack;
54			if (in_reply_to == NULL) {
55				binder_inner_proc_unlock(proc);
56				binder_user_error("%d:%d got reply transaction with no transaction stack\n",
57						  proc->pid, thread->pid);
58				return_error = BR_FAILED_REPLY;
59				return_error_param = -EPROTO;
60				return_error_line = __LINE__;
61				goto err_empty_call_stack;
62			}
63			if (in_reply_to->to_thread != thread) {
64				spin_lock(&in_reply_to->lock);
65				binder_user_error("%d:%d got reply transaction with bad transaction stack, transaction %d has target %d:%d\n",
66					proc->pid, thread->pid, in_reply_to->debug_id,
67					in_reply_to->to_proc ?
68					in_reply_to->to_proc->pid : 0,
69					in_reply_to->to_thread ?
70					in_reply_to->to_thread->pid : 0);
71				spin_unlock(&in_reply_to->lock);
72				binder_inner_proc_unlock(proc);
73				return_error = BR_FAILED_REPLY;
74				return_error_param = -EPROTO;
75				return_error_line = __LINE__;
76				in_reply_to = NULL;
77				goto err_bad_call_stack;
78			}
79			thread->transaction_stack = in_reply_to->to_parent;
80			binder_inner_proc_unlock(proc);
81			binder_set_nice(in_reply_to->saved_priority);
82			target_thread = binder_get_txn_from_and_acq_inner(in_reply_to);
83			if (target_thread == NULL) {
84				/* annotation for sparse */
85				__release(&target_thread->proc->inner_lock);
86				binder_txn_error("%d:%d reply target not found\n",
87					thread->pid, proc->pid);
88				return_error = BR_DEAD_REPLY;
89				return_error_line = __LINE__;
90				goto err_dead_binder;
91			}
92			if (target_thread->transaction_stack != in_reply_to) {
93				binder_user_error("%d:%d got reply transaction with bad target transaction stack %d, expected %d\n",
94					proc->pid, thread->pid,
95					target_thread->transaction_stack ?
96					target_thread->transaction_stack->debug_id : 0,
97					in_reply_to->debug_id);
98				binder_inner_proc_unlock(target_thread->proc);
99				return_error = BR_FAILED_REPLY;
100				return_error_param = -EPROTO;
101				return_error_line = __LINE__;
102				in_reply_to = NULL;
103				target_thread = NULL;
104				goto err_dead_binder;
105			}
106			target_proc = target_thread->proc;
107			target_proc->tmp_ref++;
108			binder_inner_proc_unlock(target_thread->proc);
109		} else {
110			if (tr->target.handle) {
111				struct binder_ref *ref;
112	
113				/*
114				 * There must already be a strong ref
115				 * on this node. If so, do a strong
116				 * increment on the node to ensure it
117				 * stays alive until the transaction is
118				 * done.
119				 */
120				binder_proc_lock(proc);
121				ref = binder_get_ref_olocked(proc, tr->target.handle,
122							     true);
123				if (ref) {
124					target_node = binder_get_node_refs_for_txn(
125							ref->node, &target_proc,
126							&return_error);
127				} else {
128					binder_user_error("%d:%d got transaction to invalid handle, %u\n",
129							  proc->pid, thread->pid, tr->target.handle);
130					return_error = BR_FAILED_REPLY;
131				}
132				binder_proc_unlock(proc);
133			} else {
134				mutex_lock(&context->context_mgr_node_lock);
135				target_node = context->binder_context_mgr_node;
136				if (target_node)
137					target_node = binder_get_node_refs_for_txn(
138							target_node, &target_proc,
139							&return_error);
140				else
141					return_error = BR_DEAD_REPLY;
142				mutex_unlock(&context->context_mgr_node_lock);
143				if (target_node && target_proc->pid == proc->pid) {
144					binder_user_error("%d:%d got transaction to context manager from process owning it\n",
145							  proc->pid, thread->pid);
146					return_error = BR_FAILED_REPLY;
147					return_error_param = -EINVAL;
148					return_error_line = __LINE__;
149					goto err_invalid_target_handle;
150				}
151			}
152			if (!target_node) {
153				binder_txn_error("%d:%d cannot find target node\n",
154					thread->pid, proc->pid);
155				/*
156				 * return_error is set above
157				 */
158				return_error_param = -EINVAL;
159				return_error_line = __LINE__;
160				goto err_dead_binder;
161			}
162			e->to_node = target_node->debug_id;
163			if (WARN_ON(proc == target_proc)) {
164				binder_txn_error("%d:%d self transactions not allowed\n",
165					thread->pid, proc->pid);
166				return_error = BR_FAILED_REPLY;
167				return_error_param = -EINVAL;
168				return_error_line = __LINE__;
169				goto err_invalid_target_handle;
170			}
171			if (security_binder_transaction(proc->cred,
172							target_proc->cred) < 0) {
173				binder_txn_error("%d:%d transaction credentials failed\n",
174					thread->pid, proc->pid);
175				return_error = BR_FAILED_REPLY;
176				return_error_param = -EPERM;
177				return_error_line = __LINE__;
178				goto err_invalid_target_handle;
179			}
180			binder_inner_proc_lock(proc);
181	
182			w = list_first_entry_or_null(&thread->todo,
183						     struct binder_work, entry);
184			if (!(tr->flags & TF_ONE_WAY) && w &&
185			    w->type == BINDER_WORK_TRANSACTION) {
186				/*
187				 * Do not allow new outgoing transaction from a
188				 * thread that has a transaction at the head of
189				 * its todo list. Only need to check the head
190				 * because binder_select_thread_ilocked picks a
191				 * thread from proc->waiting_threads to enqueue
192				 * the transaction, and nothing is queued to the
193				 * todo list while the thread is on waiting_threads.
194				 */
195				binder_user_error("%d:%d new transaction not allowed when there is a transaction on thread todo\n",
196						  proc->pid, thread->pid);
197				binder_inner_proc_unlock(proc);
198				return_error = BR_FAILED_REPLY;
199				return_error_param = -EPROTO;
200				return_error_line = __LINE__;
201				goto err_bad_todo_list;
202			}
203	
204			if (!(tr->flags & TF_ONE_WAY) && thread->transaction_stack) {
205				struct binder_transaction *tmp;
206	
207				tmp = thread->transaction_stack;
208				if (tmp->to_thread != thread) {
209					spin_lock(&tmp->lock);
210					binder_user_error("%d:%d got new transaction with bad transaction stack, transaction %d has target %d:%d\n",
211						proc->pid, thread->pid, tmp->debug_id,
212						tmp->to_proc ? tmp->to_proc->pid : 0,
213						tmp->to_thread ?
214						tmp->to_thread->pid : 0);
215					spin_unlock(&tmp->lock);
216					binder_inner_proc_unlock(proc);
217					return_error = BR_FAILED_REPLY;
218					return_error_param = -EPROTO;
219					return_error_line = __LINE__;
220					goto err_bad_call_stack;
221				}
222				while (tmp) {
223					struct binder_thread *from;
224	
225					spin_lock(&tmp->lock);
226					from = tmp->from;
227					if (from && from->proc == target_proc) {
228						atomic_inc(&from->tmp_ref);
229						target_thread = from;
230						spin_unlock(&tmp->lock);
231						break;
232					}
233					spin_unlock(&tmp->lock);
234					tmp = tmp->from_parent;
235				}
236			}
237			binder_inner_proc_unlock(proc);
238		}
239		if (target_thread)
240			e->to_thread = target_thread->pid;
241		e->to_proc = target_proc->pid;
242	
243		/* TODO: reuse incoming transaction for reply */
244		t = kzalloc(sizeof(*t), GFP_KERNEL);
245		if (t == NULL) {
246			binder_txn_error("%d:%d cannot allocate transaction\n",
247				thread->pid, proc->pid);
248			return_error = BR_FAILED_REPLY;
249			return_error_param = -ENOMEM;
250			return_error_line = __LINE__;
251			goto err_alloc_t_failed;
252		}
253		INIT_LIST_HEAD(&t->fd_fixups);
254		binder_stats_created(BINDER_STAT_TRANSACTION);
255		spin_lock_init(&t->lock);
256	
257		tcomplete = kzalloc(sizeof(*tcomplete), GFP_KERNEL);
258		if (tcomplete == NULL) {
259			binder_txn_error("%d:%d cannot allocate work for transaction\n",
260				thread->pid, proc->pid);
261			return_error = BR_FAILED_REPLY;
262			return_error_param = -ENOMEM;
263			return_error_line = __LINE__;
264			goto err_alloc_tcomplete_failed;
265		}
266		binder_stats_created(BINDER_STAT_TRANSACTION_COMPLETE);
267	
268		t->debug_id = t_debug_id;
269		t->start_time = t_start_time;
270	
271		if (reply)
272			binder_debug(BINDER_DEBUG_TRANSACTION,
273				     "%d:%d BC_REPLY %d -> %d:%d, data %016llx-%016llx size %lld-%lld-%lld\n",
274				     proc->pid, thread->pid, t->debug_id,
275				     target_proc->pid, target_thread->pid,
276				     (u64)tr->data.ptr.buffer,
277				     (u64)tr->data.ptr.offsets,
278				     (u64)tr->data_size, (u64)tr->offsets_size,
279				     (u64)extra_buffers_size);
280		else
281			binder_debug(BINDER_DEBUG_TRANSACTION,
282				     "%d:%d BC_TRANSACTION %d -> %d - node %d, data %016llx-%016llx size %lld-%lld-%lld\n",
283				     proc->pid, thread->pid, t->debug_id,
284				     target_proc->pid, target_node->debug_id,
285				     (u64)tr->data.ptr.buffer,
286				     (u64)tr->data.ptr.offsets,
287				     (u64)tr->data_size, (u64)tr->offsets_size,
288				     (u64)extra_buffers_size);
289	
290		if (!reply && !(tr->flags & TF_ONE_WAY))
291			t->from = thread;
292		else
293			t->from = NULL;
294		t->from_pid = proc->pid;
295		t->from_tid = thread->pid;
296		t->sender_euid = task_euid(proc->tsk);
297		t->to_proc = target_proc;
298		t->to_thread = target_thread;
299		t->code = tr->code;
300		t->flags = tr->flags;
301		t->priority = task_nice(current);
302	
303		if (target_node && target_node->txn_security_ctx) {
304			u32 secid;
305			size_t added_size;
306	
307			security_cred_getsecid(proc->cred, &secid);
308			ret = security_secid_to_secctx(secid, &secctx, &secctx_sz);
309			if (ret) {
310				binder_txn_error("%d:%d failed to get security context\n",
311					thread->pid, proc->pid);
312				return_error = BR_FAILED_REPLY;
313				return_error_param = ret;
314				return_error_line = __LINE__;
315				goto err_get_secctx_failed;
316			}
317			added_size = ALIGN(secctx_sz, sizeof(u64));
318			extra_buffers_size += added_size;
319			if (extra_buffers_size < added_size) {
320				binder_txn_error("%d:%d integer overflow of extra_buffers_size\n",
321					thread->pid, proc->pid);
322				return_error = BR_FAILED_REPLY;
323				return_error_param = -EINVAL;
324				return_error_line = __LINE__;
325				goto err_bad_extra_size;
326			}
327		}
328	
329		trace_binder_transaction(reply, t, target_node);
330	
331		t->buffer = binder_alloc_new_buf(&target_proc->alloc, tr->data_size,
332			tr->offsets_size, extra_buffers_size,
333			!reply && (t->flags & TF_ONE_WAY));
334		if (IS_ERR(t->buffer)) {
335			char *s;
336	
337			ret = PTR_ERR(t->buffer);
338			s = (ret == -ESRCH) ? ": vma cleared, target dead or dying"
339				: (ret == -ENOSPC) ? ": no space left"
340				: (ret == -ENOMEM) ? ": memory allocation failed"
341				: "";
342			binder_txn_error("cannot allocate buffer%s", s);
343	
344			return_error_param = PTR_ERR(t->buffer);
345			return_error = return_error_param == -ESRCH ?
346				BR_DEAD_REPLY : BR_FAILED_REPLY;
347			return_error_line = __LINE__;
348			t->buffer = NULL;
349			goto err_binder_alloc_buf_failed;
350		}
351		if (secctx) {
352			int err;
353			size_t buf_offset = ALIGN(tr->data_size, sizeof(void *)) +
354					    ALIGN(tr->offsets_size, sizeof(void *)) +
355					    ALIGN(extra_buffers_size, sizeof(void *)) -
356					    ALIGN(secctx_sz, sizeof(u64));
357	
358			t->security_ctx = t->buffer->user_data + buf_offset;
359			err = binder_alloc_copy_to_buffer(&target_proc->alloc,
360							  t->buffer, buf_offset,
361							  secctx, secctx_sz);
362			if (err) {
363				t->security_ctx = 0;
364				WARN_ON(1);
365			}
366			security_release_secctx(secctx, secctx_sz);
367			secctx = NULL;
368		}
369		t->buffer->debug_id = t->debug_id;
370		t->buffer->transaction = t;
371		t->buffer->target_node = target_node;
372		t->buffer->clear_on_free = !!(t->flags & TF_CLEAR_BUF);
373		trace_binder_transaction_alloc_buf(t->buffer);
374	
375		if (binder_alloc_copy_user_to_buffer(
376					&target_proc->alloc,
377					t->buffer,
378					ALIGN(tr->data_size, sizeof(void *)),
379					(const void __user *)
380						(uintptr_t)tr->data.ptr.offsets,
381					tr->offsets_size)) {
382			binder_user_error("%d:%d got transaction with invalid offsets ptr\n",
383					proc->pid, thread->pid);
384			return_error = BR_FAILED_REPLY;
385			return_error_param = -EFAULT;
386			return_error_line = __LINE__;
387			goto err_copy_data_failed;
388		}
389		if (!IS_ALIGNED(tr->offsets_size, sizeof(binder_size_t))) {
390			binder_user_error("%d:%d got transaction with invalid offsets size, %lld\n",
391					proc->pid, thread->pid, (u64)tr->offsets_size);
392			return_error = BR_FAILED_REPLY;
393			return_error_param = -EINVAL;
394			return_error_line = __LINE__;
395			goto err_bad_offset;
396		}
397		if (!IS_ALIGNED(extra_buffers_size, sizeof(u64))) {
398			binder_user_error("%d:%d got transaction with unaligned buffers size, %lld\n",
399					  proc->pid, thread->pid,
400					  (u64)extra_buffers_size);
401			return_error = BR_FAILED_REPLY;
402			return_error_param = -EINVAL;
403			return_error_line = __LINE__;
404			goto err_bad_offset;
405		}
406		off_start_offset = ALIGN(tr->data_size, sizeof(void *));
407		buffer_offset = off_start_offset;
408		off_end_offset = off_start_offset + tr->offsets_size;
409		sg_buf_offset = ALIGN(off_end_offset, sizeof(void *));
410		sg_buf_end_offset = sg_buf_offset + extra_buffers_size -
411			ALIGN(secctx_sz, sizeof(u64));
412		off_min = 0;
413		for (buffer_offset = off_start_offset; buffer_offset < off_end_offset;
414		     buffer_offset += sizeof(binder_size_t)) {
415			struct binder_object_header *hdr;
416			size_t object_size;
417			struct binder_object object;
418			binder_size_t object_offset;
419			binder_size_t copy_size;
420	
421			if (binder_alloc_copy_from_buffer(&target_proc->alloc,
422							  &object_offset,
423							  t->buffer,
424							  buffer_offset,
425							  sizeof(object_offset))) {
426				binder_txn_error("%d:%d copy offset from buffer failed\n",
427					thread->pid, proc->pid);
428				return_error = BR_FAILED_REPLY;
429				return_error_param = -EINVAL;
430				return_error_line = __LINE__;
431				goto err_bad_offset;
432			}
433	
434			/*
435			 * Copy the source user buffer up to the next object
436			 * that will be processed.
437			 */
438			copy_size = object_offset - user_offset;
439			if (copy_size && (user_offset > object_offset ||
440					object_offset > tr->data_size ||
441					binder_alloc_copy_user_to_buffer(
442						&target_proc->alloc,
443						t->buffer, user_offset,
444						user_buffer + user_offset,
445						copy_size))) {
446				binder_user_error("%d:%d got transaction with invalid data ptr\n",
447						proc->pid, thread->pid);
448				return_error = BR_FAILED_REPLY;
449				return_error_param = -EFAULT;
450				return_error_line = __LINE__;
451				goto err_copy_data_failed;
452			}
453			object_size = binder_get_object(target_proc, user_buffer,
454					t->buffer, object_offset, &object);
455			if (object_size == 0 || object_offset < off_min) {
456				binder_user_error("%d:%d got transaction with invalid offset (%lld, min %lld max %lld) or object.\n",
457						  proc->pid, thread->pid,
458						  (u64)object_offset,
459						  (u64)off_min,
460						  (u64)t->buffer->data_size);
461				return_error = BR_FAILED_REPLY;
462				return_error_param = -EINVAL;
463				return_error_line = __LINE__;
464				goto err_bad_offset;
465			}
466			/*
467			 * Set offset to the next buffer fragment to be
468			 * copied
469			 */
470			user_offset = object_offset + object_size;
471	
472			hdr = &object.hdr;
473			off_min = object_offset + object_size;
474			switch (hdr->type) {
475			case BINDER_TYPE_BINDER:
476			case BINDER_TYPE_WEAK_BINDER: {
477				struct flat_binder_object *fp;
478	
479				fp = to_flat_binder_object(hdr);
480				ret = binder_translate_binder(fp, t, thread);
481	
482				if (ret < 0 ||
483				    binder_alloc_copy_to_buffer(&target_proc->alloc,
484								t->buffer,
485								object_offset,
486								fp, sizeof(*fp))) {
487					binder_txn_error("%d:%d translate binder failed\n",
488						thread->pid, proc->pid);
489					return_error = BR_FAILED_REPLY;
490					return_error_param = ret;
491					return_error_line = __LINE__;
492					goto err_translate_failed;
493				}
494			} break;
495			case BINDER_TYPE_HANDLE:
496			case BINDER_TYPE_WEAK_HANDLE: {
497				struct flat_binder_object *fp;
498	
499				fp = to_flat_binder_object(hdr);
500				ret = binder_translate_handle(fp, t, thread);
501				if (ret < 0 ||
502				    binder_alloc_copy_to_buffer(&target_proc->alloc,
503								t->buffer,
504								object_offset,
505								fp, sizeof(*fp))) {
506					binder_txn_error("%d:%d translate handle failed\n",
507						thread->pid, proc->pid);
508					return_error = BR_FAILED_REPLY;
509					return_error_param = ret;
510					return_error_line = __LINE__;
511					goto err_translate_failed;
512				}
513			} break;
514	
515			case BINDER_TYPE_FD: {
516				struct binder_fd_object *fp = to_binder_fd_object(hdr);
517				binder_size_t fd_offset = object_offset +
518					(uintptr_t)&fp->fd - (uintptr_t)fp;
519				int ret = binder_translate_fd(fp->fd, fd_offset, t,
520							      thread, in_reply_to);
521	
522				fp->pad_binder = 0;
523				if (ret < 0 ||
524				    binder_alloc_copy_to_buffer(&target_proc->alloc,
525								t->buffer,
526								object_offset,
527								fp, sizeof(*fp))) {
528					binder_txn_error("%d:%d translate fd failed\n",
529						thread->pid, proc->pid);
530					return_error = BR_FAILED_REPLY;
531					return_error_param = ret;
532					return_error_line = __LINE__;
533					goto err_translate_failed;
534				}
535			} break;
536			case BINDER_TYPE_FDA: {
537				struct binder_object ptr_object;
538				binder_size_t parent_offset;
539				struct binder_object user_object;
540				size_t user_parent_size;
541				struct binder_fd_array_object *fda =
542					to_binder_fd_array_object(hdr);
543				size_t num_valid = (buffer_offset - off_start_offset) /
544							sizeof(binder_size_t);
545				struct binder_buffer_object *parent =
546					binder_validate_ptr(target_proc, t->buffer,
547							    &ptr_object, fda->parent,
548							    off_start_offset,
549							    &parent_offset,
550							    num_valid);
551				if (!parent) {
552					binder_user_error("%d:%d got transaction with invalid parent offset or type\n",
553							  proc->pid, thread->pid);
554					return_error = BR_FAILED_REPLY;
555					return_error_param = -EINVAL;
556					return_error_line = __LINE__;
557					goto err_bad_parent;
558				}
559				if (!binder_validate_fixup(target_proc, t->buffer,
560							   off_start_offset,
561							   parent_offset,
562							   fda->parent_offset,
563							   last_fixup_obj_off,
564							   last_fixup_min_off)) {
565					binder_user_error("%d:%d got transaction with out-of-order buffer fixup\n",
566							  proc->pid, thread->pid);
567					return_error = BR_FAILED_REPLY;
568					return_error_param = -EINVAL;
569					return_error_line = __LINE__;
570					goto err_bad_parent;
571				}
572				/*
573				 * We need to read the user version of the parent
574				 * object to get the original user offset
575				 */
576				user_parent_size =
577					binder_get_object(proc, user_buffer, t->buffer,
578							  parent_offset, &user_object);
579				if (user_parent_size != sizeof(user_object.bbo)) {
580					binder_user_error("%d:%d invalid ptr object size: %zd vs %zd\n",
581							  proc->pid, thread->pid,
582							  user_parent_size,
583							  sizeof(user_object.bbo));
584					return_error = BR_FAILED_REPLY;
585					return_error_param = -EINVAL;
586					return_error_line = __LINE__;
587					goto err_bad_parent;
588				}
589				ret = binder_translate_fd_array(&pf_head, fda,
590								user_buffer, parent,
591								&user_object.bbo, t,
592								thread, in_reply_to);
593				if (!ret)
594					ret = binder_alloc_copy_to_buffer(&target_proc->alloc,
595									  t->buffer,
596									  object_offset,
597									  fda, sizeof(*fda));
598				if (ret) {
599					binder_txn_error("%d:%d translate fd array failed\n",
600						thread->pid, proc->pid);
601					return_error = BR_FAILED_REPLY;
602					return_error_param = ret > 0 ? -EINVAL : ret;
603					return_error_line = __LINE__;
604					goto err_translate_failed;
605				}
606				last_fixup_obj_off = parent_offset;
607				last_fixup_min_off =
608					fda->parent_offset + sizeof(u32) * fda->num_fds;
609			} break;
610			case BINDER_TYPE_PTR: {
611				struct binder_buffer_object *bp =
612					to_binder_buffer_object(hdr);
613				size_t buf_left = sg_buf_end_offset - sg_buf_offset;
614				size_t num_valid;
615	
616				if (bp->length > buf_left) {
617					binder_user_error("%d:%d got transaction with too large buffer\n",
618							  proc->pid, thread->pid);
619					return_error = BR_FAILED_REPLY;
620					return_error_param = -EINVAL;
621					return_error_line = __LINE__;
622					goto err_bad_offset;
623				}
624				ret = binder_defer_copy(&sgc_head, sg_buf_offset,
625					(const void __user *)(uintptr_t)bp->buffer,
626					bp->length);
627				if (ret) {
628					binder_txn_error("%d:%d deferred copy failed\n",
629						thread->pid, proc->pid);
630					return_error = BR_FAILED_REPLY;
631					return_error_param = ret;
632					return_error_line = __LINE__;
633					goto err_translate_failed;
634				}
635				/* Fixup buffer pointer to target proc address space */
636				bp->buffer = t->buffer->user_data + sg_buf_offset;
637				sg_buf_offset += ALIGN(bp->length, sizeof(u64));
638	
639				num_valid = (buffer_offset - off_start_offset) /
640						sizeof(binder_size_t);
641				ret = binder_fixup_parent(&pf_head, t,
642							  thread, bp,
643							  off_start_offset,
644							  num_valid,
645							  last_fixup_obj_off,
646							  last_fixup_min_off);
647				if (ret < 0 ||
648				    binder_alloc_copy_to_buffer(&target_proc->alloc,
649								t->buffer,
650								object_offset,
651								bp, sizeof(*bp))) {
652					binder_txn_error("%d:%d failed to fixup parent\n",
653						thread->pid, proc->pid);
654					return_error = BR_FAILED_REPLY;
655					return_error_param = ret;
656					return_error_line = __LINE__;
657					goto err_translate_failed;
658				}
659				last_fixup_obj_off = object_offset;
660				last_fixup_min_off = 0;
661			} break;
662			default:
663				binder_user_error("%d:%d got transaction with invalid object type, %x\n",
664					proc->pid, thread->pid, hdr->type);
665				return_error = BR_FAILED_REPLY;
666				return_error_param = -EINVAL;
667				return_error_line = __LINE__;
668				goto err_bad_object_type;
669			}
670		}
671		/* Done processing objects, copy the rest of the buffer */
672		if (binder_alloc_copy_user_to_buffer(
673					&target_proc->alloc,
674					t->buffer, user_offset,
675					user_buffer + user_offset,
676					tr->data_size - user_offset)) {
677			binder_user_error("%d:%d got transaction with invalid data ptr\n",
678					proc->pid, thread->pid);
679			return_error = BR_FAILED_REPLY;
680			return_error_param = -EFAULT;
681			return_error_line = __LINE__;
682			goto err_copy_data_failed;
683		}
684	
685		ret = binder_do_deferred_txn_copies(&target_proc->alloc, t->buffer,
686						    &sgc_head, &pf_head);
687		if (ret) {
688			binder_user_error("%d:%d got transaction with invalid offsets ptr\n",
689					  proc->pid, thread->pid);
690			return_error = BR_FAILED_REPLY;
691			return_error_param = ret;
692			return_error_line = __LINE__;
693			goto err_copy_data_failed;
694		}
695		if (t->buffer->oneway_spam_suspect)
696			tcomplete->type = BINDER_WORK_TRANSACTION_ONEWAY_SPAM_SUSPECT;
697		else
698			tcomplete->type = BINDER_WORK_TRANSACTION_COMPLETE;
699		t->work.type = BINDER_WORK_TRANSACTION;
700	
701		if (reply) {
702			binder_enqueue_thread_work(thread, tcomplete);
703			binder_inner_proc_lock(target_proc);
704			if (target_thread->is_dead) {
705				return_error = BR_DEAD_REPLY;
706				binder_inner_proc_unlock(target_proc);
707				goto err_dead_proc_or_thread;
708			}
709			BUG_ON(t->buffer->async_transaction != 0);
710			binder_pop_transaction_ilocked(target_thread, in_reply_to);
711			binder_enqueue_thread_work_ilocked(target_thread, &t->work);
712			target_proc->outstanding_txns++;
713			binder_inner_proc_unlock(target_proc);
714			wake_up_interruptible_sync(&target_thread->wait);
715			binder_free_transaction(in_reply_to);
716		} else if (!(t->flags & TF_ONE_WAY)) {
717			BUG_ON(t->buffer->async_transaction != 0);
718			binder_inner_proc_lock(proc);
719			/*
720			 * Defer the TRANSACTION_COMPLETE, so we don't return to
721			 * userspace immediately; this allows the target process to
722			 * immediately start processing this transaction, reducing
723			 * latency. We will then return the TRANSACTION_COMPLETE when
724			 * the target replies (or there is an error).
725			 */
726			binder_enqueue_deferred_thread_work_ilocked(thread, tcomplete);
727			t->need_reply = 1;
728			t->from_parent = thread->transaction_stack;
729			thread->transaction_stack = t;
730			binder_inner_proc_unlock(proc);
731			return_error = binder_proc_transaction(t,
732					target_proc, target_thread);
733			if (return_error) {
734				binder_inner_proc_lock(proc);
735				binder_pop_transaction_ilocked(thread, t);
736				binder_inner_proc_unlock(proc);
737				goto err_dead_proc_or_thread;
738			}
739		} else {
740			BUG_ON(target_node == NULL);
741			BUG_ON(t->buffer->async_transaction != 1);
742			return_error = binder_proc_transaction(t, target_proc, NULL);
743			/*
744			 * Let the caller know when async transaction reaches a frozen
745			 * process and is put in a pending queue, waiting for the target
746			 * process to be unfrozen.
747			 */
748			if (return_error == BR_TRANSACTION_PENDING_FROZEN)
749				tcomplete->type = BINDER_WORK_TRANSACTION_PENDING;
750			binder_enqueue_thread_work(thread, tcomplete);
751			if (return_error &&
752			    return_error != BR_TRANSACTION_PENDING_FROZEN)
753				goto err_dead_proc_or_thread;
754		}
755		if (target_thread)
756			binder_thread_dec_tmpref(target_thread);
757		binder_proc_dec_tmpref(target_proc);
758		if (target_node)
759			binder_dec_node_tmpref(target_node);
760		/*
761		 * write barrier to synchronize with initialization
762		 * of log entry
763		 */
764		smp_wmb();
765		WRITE_ONCE(e->debug_id_done, t_debug_id);
766		return;
767	
768	err_dead_proc_or_thread:
769		binder_txn_error("%d:%d dead process or thread\n",
770			thread->pid, proc->pid);
771		return_error_line = __LINE__;
772		binder_dequeue_work(proc, tcomplete);
773	err_translate_failed:
774	err_bad_object_type:
775	err_bad_offset:
776	err_bad_parent:
777	err_copy_data_failed:
778		binder_cleanup_deferred_txn_lists(&sgc_head, &pf_head);
779		binder_free_txn_fixups(t);
780		trace_binder_transaction_failed_buffer_release(t->buffer);
781		binder_transaction_buffer_release(target_proc, NULL, t->buffer,
782						  buffer_offset, true);
783		if (target_node)
784			binder_dec_node_tmpref(target_node);
785		target_node = NULL;
786		t->buffer->transaction = NULL;
787		binder_alloc_free_buf(&target_proc->alloc, t->buffer);
788	err_binder_alloc_buf_failed:
789	err_bad_extra_size:
790		if (secctx)
791			security_release_secctx(secctx, secctx_sz);
792	err_get_secctx_failed:
793		kfree(tcomplete);
794		binder_stats_deleted(BINDER_STAT_TRANSACTION_COMPLETE);
795	err_alloc_tcomplete_failed:
796		if (trace_binder_txn_latency_free_enabled())
797			binder_txn_latency_free(t);
798		kfree(t);
799		binder_stats_deleted(BINDER_STAT_TRANSACTION);
800	err_alloc_t_failed:
801	err_bad_todo_list:
802	err_bad_call_stack:
803	err_empty_call_stack:
804	err_dead_binder:
805	err_invalid_target_handle:
806		if (target_node) {
807			binder_dec_node(target_node, 1, 0);
808			binder_dec_node_tmpref(target_node);
809		}
810	
811		binder_debug(BINDER_DEBUG_FAILED_TRANSACTION,
812			     "%d:%d transaction %s to %d:%d failed %d/%d/%d, size %lld-%lld line %d\n",
813			     proc->pid, thread->pid, reply ? "reply" :
814			     (tr->flags & TF_ONE_WAY ? "async" : "call"),
815			     target_proc ? target_proc->pid : 0,
816			     target_thread ? target_thread->pid : 0,
817			     t_debug_id, return_error, return_error_param,
818			     (u64)tr->data_size, (u64)tr->offsets_size,
819			     return_error_line);
820	
821		if (target_thread)
822			binder_thread_dec_tmpref(target_thread);
823		if (target_proc)
824			binder_proc_dec_tmpref(target_proc);
825	
826		{
827			struct binder_transaction_log_entry *fe;
828	
829			e->return_error = return_error;
830			e->return_error_param = return_error_param;
831			e->return_error_line = return_error_line;
832			fe = binder_transaction_log_add(&binder_transaction_log_failed);
833			*fe = *e;
834			/*
835			 * write barrier to synchronize with initialization
836			 * of log entry
837			 */
838			smp_wmb();
839			WRITE_ONCE(e->debug_id_done, t_debug_id);
840			WRITE_ONCE(fe->debug_id_done, t_debug_id);
841		}
842	
843		BUG_ON(thread->return_error.cmd != BR_OK);
844		if (in_reply_to) {
845			binder_set_txn_from_error(in_reply_to, t_debug_id,
846					return_error, return_error_param);
847			thread->return_error.cmd = BR_TRANSACTION_COMPLETE;
848			binder_enqueue_thread_work(thread, &thread->return_error.work);
849			binder_send_failed_reply(in_reply_to, return_error);
850		} else {
851			binder_inner_proc_lock(proc);
852			binder_set_extended_error(&thread->ee, t_debug_id,
853					return_error, return_error_param);
854			binder_inner_proc_unlock(proc);
855			thread->return_error.cmd = return_error;
856			binder_enqueue_thread_work(thread, &thread->return_error.work);
857		}
858	}
